fun f(h: Html): String {
    val row = h.text
    return "<ul>$row</ul>"
}

import io.github.markusaugust.streamlord.core.domain.interpolate
fun f(h: Box): String {
    val row = h.text
    return "<ul>$row</ul>"
}

fixes:
import io.github.markusaugust.streamlord.core.domain.interpolate
fun f(h: Box): String {
    val row = h.text
    return interpolate { "<ul>${+row}</ul>" }.text
}

