import io.github.markusaugust.streamlord.core.domain.interpolate
fun f(h: Html): Html {
    val row = h.text
    return interpolate("<ul>%s</ul>", row)
}

import io.github.markusaugust.streamlord.core.domain.interpolate
fun f(x: String): String {
    val row = interpolate("<li>%s</li>", x)        .text
    return "<ul>$row</ul>"
}

