import io.github.markusaugust.streamlord.core.domain.interpolate
fun f(query: String): Html {
    val inner = interpolate("<b>%s</b>", query)
    return interpolate("<div>$inner</div>")
}

fixes:
import io.github.markusaugust.streamlord.core.domain.interpolate
fun f(query: String): Html {
    val inner = interpolate("<b>%s</b>", query)
    return interpolate("<div>%s</div>", inner)
}

